mapper.select:
select con.Con_Name as conName, con.Con_Code as conCode,
c1.C_Name_History as disUnitNameHistory, c2.C_Name_History as disUnitDNameHistory, c1.C_Name as disUnitName, c2.C_Name as disUnitDName, c1.C_Abbreviation as disUnitAbbName, c2.C_Abbreviation as disUnitDAbbName, mn.* from Con_Sup_Disclosure mn left join Con_Contract con on con.Con_Id=mn.Con_Id
left join SYS_Company c1 on mn.Dis_Unit_Id=c1.C_Id left join SYS_Company c2 on mn.Dis_Unit_D_Id=c2.C_Id ${params.authSql}
and mn.Te_Id = #{params.teId}
and mn.P_Id=#{params.pId}
and mn.Dis_Type like concat('%',#{params.disType},'%')
and likePname(#{params.pName},pro.P_Id)=true
and pro.P_Name like concat('%',#{params.pName},'%')
and con.Con_Name like concat('%',#{params.conName},'%')
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Dis_Create_Time DESC
